// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address ownerAddr, address newOwner) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(ownerAddr);

        assertEq(c.owner(), ownerAddr);

        vm.prank(ownerAddr);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == newOwner);
    }
}
